// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }

    function testFuzz_property(address newOwner) public {
        vm.assume(c.owner() != address(0));
        vm.prank(c.owner());
        bool success = true;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }
        if (success) {
            assertTrue(c.owner() != address(0));
        }
    }
}
